package com.rpgtemplate.nothingthere.client;

import com.mojang.blaze3d.vertex.PoseStack;
import com.mojang.blaze3d.vertex.VertexConsumer;
import java.io.BufferedInputStream;
import java.io.DataInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import net.minecraft.client.model.geom.ModelPart;
import org.joml.Matrix3f;
import org.joml.Matrix4f;
import org.joml.Quaternionf;
import org.joml.Vector3f;

/**
 * Draws the 一无所有 hand weapons (generated by gen/gen_nt_hands.py). Each part belongs to one vanilla arm frame
 * (rightArm = 2, leftArm = 3) and is stored relative to that arm's pivot, so the vanilla arm animation moves it.
 *
 * Both arms are flesh (red) arm stubs; NtBodyClient hides the vanilla arms of a human.
 *   right hand: the hammer, always.
 *   left hand: the flesh arm, always; the blade in the hand in blade form (技能 4 变形, 手刀) and on goodbye.
 *
 * Visibility flags per part:
 *   0 always, 2 blade (blade form or goodbye), 4 never (not drawn).
 */
public final class NtBodyMesh {
    public static final int FRAME_RIGHT_ARM = 2;
    public static final int FRAME_LEFT_ARM = 3;
    /** The 蛋 (茧) body and eyes (gen_nt_egg.py). Not a hand frame: drawn by drawEgg only. */
    public static final int FRAME_EGG = 5;

    public static final int FLAG_ALWAYS = 0;
    public static final int FLAG_BLADE = 2;
    public static final int FLAG_NEVER = 4;


    private static final String DATA_PATH = "assets/rpgtemplate/models/nothing_there/hands.bin";
    private static volatile List<Part> parts;
    private static float[] eggBoundsCache;

    private NtBodyMesh() {
    }

    /** One part: positions and normals in frame space, colours 0-255, triangle indices. */
    private record Part(String name, int frame, int flag, float[] pos, float[] nrm, int[] col, int[] idx) {
    }

    /**
     * Third person. Both arms are drawn (flesh stubs). The blade is in the left hand in blade form and on goodbye.
     *
     * @param goodbye the left blade is out for a goodbye strike
     * @param blade   the player is in blade form (技能 4)
     */
    public static void drawHands(PoseStack pose, VertexConsumer vc, int light, int overlay,
                                 ModelPart rightArm, ModelPart leftArm, boolean goodbye, boolean blade) {
        drawFrame(pose, vc, light, overlay, rightArm, FRAME_RIGHT_ARM, goodbye, blade);
        drawFrame(pose, vc, light, overlay, leftArm, FRAME_LEFT_ARM, goodbye, blade);
    }

    /**
     * First person: one hand. The right arm carries the hammer. The left arm is drawn only for goodbye, the same
     * as drawHands. Called from the hand render event with that hand's pose, as vanilla renderHand does: the arm
     * pitch is reset first.
     */
    public static void drawArmFirstPerson(PoseStack pose, VertexConsumer vc, int light, int overlay,
                                          ModelPart arm, boolean right, boolean goodbye, boolean blade) {
        arm.f_104203_ = 0.0F;
        drawFrame(pose, vc, light, overlay, arm, right ? FRAME_RIGHT_ARM : FRAME_LEFT_ARM, goodbye, blade);
    }

    /**
     * The cocoon egg, drawn in the layer pose as it is (no arm pivot). The egg's origin is set so that the ground
     * is at the model's feet (see gen_nt_egg.py).
     */
    public static void drawEgg(PoseStack pose, VertexConsumer vc, int light, int overlay) {
        draw(pose, vc, light, overlay, FRAME_EGG, false, false);
    }

    /** Same transform order as ModelPart.translateAndRotate: offset, then Z, Y, X rotations. */
    private static void drawFrame(PoseStack pose, VertexConsumer vc, int light, int overlay,
                                  ModelPart part, int frame, boolean goodbye, boolean blade) {
        pose.m_85836_();
        pose.m_85837_(part.f_104200_ / 16.0, part.f_104201_ / 16.0, part.f_104202_ / 16.0);
        if (part.f_104205_ != 0.0F) {
            pose.m_252781_(new Quaternionf().rotationZ(part.f_104205_));
        }
        if (part.f_104204_ != 0.0F) {
            pose.m_252781_(new Quaternionf().rotationY(part.f_104204_));
        }
        if (part.f_104203_ != 0.0F) {
            pose.m_252781_(new Quaternionf().rotationX(part.f_104203_));
        }
        draw(pose, vc, light, overlay, frame, goodbye, blade);
        pose.m_85849_();
    }

    /** Emits the visible triangles of one frame in the current pose. */
    private static void draw(PoseStack pose, VertexConsumer vc, int light, int overlay, int frame,
                             boolean goodbye, boolean blade) {
        Matrix4f m = pose.m_85850_().m_252922_();
        Matrix3f nm = pose.m_85850_().m_252943_();
        Vector3f p = new Vector3f();
        Vector3f n = new Vector3f();
        boolean egg = frame == FRAME_EGG;
        float[] bounds = egg ? eggHeightRange() : null;
        for (Part part : parts()) {
            if (part.frame() != frame || !visible(part, goodbye, blade)) {
                continue;
            }
            float[] pos = part.pos();
            float[] nrm = part.nrm();
            int[] col = part.col();
            int[] idx = part.idx();
            // egg: the body wraps the flesh texture around its vertical axis; the eyes sample the white texel
            float[] uv = egg ? eggUv(part, bounds) : null;
            for (int k = 0; k < idx.length; k++) {
                int i = idx[k] * 3;
                m.transformPosition(pos[i], pos[i + 1], pos[i + 2], p);
                nm.transform(nrm[i], nrm[i + 1], nrm[i + 2], n);
                n.normalize();
                float u = uv == null ? 0.5F : uv[2 * k];
                float tv = uv == null ? 0.5F : uv[2 * k + 1];
                vc.m_5954_(p.x, p.y, p.z,
                    (col[i] & 0xFF) / 255.0F, (col[i + 1] & 0xFF) / 255.0F, (col[i + 2] & 0xFF) / 255.0F, 1.0F,
                    u, tv, overlay, light, n.x, n.y, n.z);
            }
        }
    }

    /** Egg body height range (y), measured once from the egg_body part. */
    private static float[] eggHeightRange() {
        if (eggBoundsCache != null) {
            return eggBoundsCache;
        }
        float lo = Float.MAX_VALUE;
        float hi = -Float.MAX_VALUE;
        for (Part part : parts()) {
            if (part.frame() != FRAME_EGG || !"egg_body".equals(part.name())) {
                continue;
            }
            float[] pos = part.pos();
            for (int i = 1; i < pos.length; i += 3) {
                lo = Math.min(lo, pos[i]);
                hi = Math.max(hi, pos[i]);
            }
        }
        if (!(hi > lo)) {
            lo = 0f;
            hi = 1f;
        }
        eggBoundsCache = new float[] {lo, hi};
        return eggBoundsCache;
    }

    /**
     * Per-corner UVs for one egg part. Body: u = angle around the vertical axis (wrapped per triangle so the seam
     * does not stretch), v = height (top of the egg at v = 0). Eyes and irises: the white texel (0.98, 0.98).
     * Returns 2 floats per index entry.
     */
    private static float[] eggUv(Part part, float[] bounds) {
        float[] pos = part.pos();
        int[] idx = part.idx();
        float[] uv = new float[idx.length * 2];
        boolean body = "egg_body".equals(part.name());
        float span = Math.max(1e-4f, bounds[1] - bounds[0]);
        for (int k = 0; k < idx.length; k++) {
            int i = idx[k] * 3;
            if (!body) {
                uv[2 * k] = 0.98F;
                uv[2 * k + 1] = 0.98F;
                continue;
            }
            double ang = Math.atan2(pos[i], pos[i + 2]);
            uv[2 * k] = (float) (ang / (2.0 * Math.PI) + 0.5);
            uv[2 * k + 1] = (bounds[1] - pos[i + 1]) / span;
        }
        if (body) {
            // a triangle that straddles the atan2 seam: lift the small u values by 1
            for (int t = 0; t + 2 < idx.length; t += 3) {
                float max = Math.max(uv[2 * t], Math.max(uv[2 * t + 2], uv[2 * t + 4]));
                float min = Math.min(uv[2 * t], Math.min(uv[2 * t + 2], uv[2 * t + 4]));
                if (max - min > 0.5F) {
                    for (int c = 0; c < 3; c++) {
                        if (uv[2 * (t + c)] < 0.5F) {
                            uv[2 * (t + c)] += 1.0F;
                        }
                    }
                }
            }
        }
        return uv;
    }

    private static boolean visible(Part part, boolean goodbye, boolean blade) {
        switch (part.flag()) {
            case FLAG_BLADE:
                return blade || goodbye;
            case FLAG_NEVER:
                return false;
            default:
                return true;
        }
    }

    private static List<Part> parts() {
        List<Part> loaded = parts;
        if (loaded == null) {
            synchronized (NtBodyMesh.class) {
                if (parts == null) {
                    parts = load();
                }
                loaded = parts;
            }
        }
        return loaded;
    }

    private static List<Part> load() {
        InputStream raw = NtBodyMesh.class.getClassLoader().getResourceAsStream(DATA_PATH);
        if (raw == null) {
            throw new IllegalStateException("missing 一无所有 hand mesh: " + DATA_PATH);
        }
        try (DataInputStream in = new DataInputStream(new BufferedInputStream(raw))) {
            byte[] magic = new byte[4];
            in.readFully(magic);
            if (!"NTM1".equals(new String(magic, StandardCharsets.US_ASCII))) {
                throw new IllegalStateException("bad 一无所有 hand mesh header");
            }
            int count = in.readInt();
            List<Part> out = new ArrayList<>(count);
            for (int i = 0; i < count; i++) {
                byte[] name = new byte[in.readUnsignedByte()];
                in.readFully(name);
                int frame = in.readUnsignedByte();
                int flag = in.readUnsignedByte();
                int nv = in.readInt();
                int nf = in.readInt();
                float[] pos = new float[nv * 3];
                float[] nrm = new float[nv * 3];
                int[] col = new int[nv * 3];
                for (int v = 0; v < nv; v++) {
                    int k = v * 3;
                    pos[k] = in.readFloat();
                    pos[k + 1] = in.readFloat();
                    pos[k + 2] = in.readFloat();
                    nrm[k] = in.readFloat();
                    nrm[k + 1] = in.readFloat();
                    nrm[k + 2] = in.readFloat();
                    col[k] = in.readUnsignedByte();
                    col[k + 1] = in.readUnsignedByte();
                    col[k + 2] = in.readUnsignedByte();
                }
                int[] idx = new int[nf * 3];
                for (int j = 0; j < idx.length; j++) {
                    idx[j] = in.readInt();
                }
                out.add(new Part(new String(name, StandardCharsets.UTF_8), frame, flag, pos, nrm, col, idx));
            }
            return List.copyOf(out);
        } catch (IOException e) {
            throw new UncheckedIOException("failed to read 一无所有 hand mesh", e);
        }
    }
}
